using FitHub.Domain.Common;using FitHub.Domain.Identity;
namespace FitHub.Domain.Bookings;
public sealed class ClassSchedule:Entity
{
    private ClassSchedule(){}
    public ClassSchedule(string name,string? description,DateTimeOffset startsAt,DateTimeOffset endsAt,int capacity,Guid instructorUserId,string? location=null){SetDetails(name,description,startsAt,endsAt,capacity,location);InstructorUserId=instructorUserId;Status=ClassScheduleStatus.PendingApproval;}
    public string Name{get;private set;}=string.Empty;public string? Description{get;private set;}public DateTimeOffset StartsAt{get;private set;}public DateTimeOffset EndsAt{get;private set;}public int Capacity{get;private set;}public string? Location{get;private set;}public ClassScheduleStatus Status{get;private set;}=ClassScheduleStatus.PendingApproval;public Guid? InstructorUserId{get;private set;}public ApplicationUser? InstructorUser{get;private set;}public Guid? ReviewedByUserId{get;private set;}public DateTimeOffset? ReviewedAt{get;private set;}public string? ReviewReason{get;private set;}public ICollection<ClassBooking> Bookings{get;}=[];

    public void Update(string name,string? description,DateTimeOffset startsAt,DateTimeOffset endsAt,int capacity,string? location,DateTimeOffset timestamp){if(Status is ClassScheduleStatus.Cancelled or ClassScheduleStatus.Completed)throw new InvalidOperationException("This class can no longer be edited.");var joined=Bookings.Count(x=>x.Status is BookingStatus.Confirmed or BookingStatus.Attended or BookingStatus.NoShow);if(capacity<joined)throw new InvalidOperationException("Capacity cannot be lower than the number of registered members.");SetDetails(name,description,startsAt,endsAt,capacity,location);Status=ClassScheduleStatus.PendingApproval;ReviewedByUserId=null;ReviewedAt=null;ReviewReason=null;MarkUpdated(timestamp);}
    public void Approve(Guid administratorId,DateTimeOffset timestamp){if(Status!=ClassScheduleStatus.PendingApproval)throw new InvalidOperationException("Only a pending class can be approved.");Status=ClassScheduleStatus.Approved;ReviewedByUserId=administratorId;ReviewedAt=timestamp;ReviewReason=null;MarkUpdated(timestamp);}
    public void Reject(Guid administratorId,string reason,DateTimeOffset timestamp){if(Status!=ClassScheduleStatus.PendingApproval)throw new InvalidOperationException("Only a pending class can be rejected.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("A rejection reason is required.",nameof(reason));Status=ClassScheduleStatus.Rejected;ReviewedByUserId=administratorId;ReviewedAt=timestamp;ReviewReason=reason.Trim();MarkUpdated(timestamp);}
    public void Cancel(DateTimeOffset timestamp){if(Status is ClassScheduleStatus.Cancelled or ClassScheduleStatus.Completed)throw new InvalidOperationException("This class can no longer be cancelled.");Status=ClassScheduleStatus.Cancelled;MarkUpdated(timestamp);}
    public void Complete(DateTimeOffset timestamp){if(Status!=ClassScheduleStatus.Approved)throw new InvalidOperationException("Only an approved class can be completed.");Status=ClassScheduleStatus.Completed;MarkUpdated(timestamp);}

    private void SetDetails(string name,string? description,DateTimeOffset startsAt,DateTimeOffset endsAt,int capacity,string? location){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Class name is required.");if(name.Trim().Length>150)throw new ArgumentException("Class name is too long.");if(description?.Trim().Length>2000)throw new ArgumentException("Class description is too long.");if(location?.Trim().Length>150)throw new ArgumentException("Class location is too long.");if(endsAt<=startsAt)throw new ArgumentException("Class end must be after its start.");if(capacity<=0)throw new ArgumentOutOfRangeException(nameof(capacity));Name=name.Trim();Description=string.IsNullOrWhiteSpace(description)?null:description.Trim();StartsAt=startsAt;EndsAt=endsAt;Capacity=capacity;Location=string.IsNullOrWhiteSpace(location)?null:location.Trim();}
}
